			}
	});

 category = () =>{
		 link_Urlpath = "/api/bookstore/classifyRankList";		
    link_Params = {
	    	"userPath": "classify"
    	};
    url = GetUrl(link_Params,link_Urlpath);
   return  JSON.parse(java.ajax(url)).data.classifyList;
		}


		category().map($=>{
			 classifyId = $.classifyId;
