     	list.map(($,index)=>{			
     	title = $.subClassifyName;	
     		sex =classifyName=="男生"?"male":"female";     		
	      url=  `@js:
	      link_Urlpath = "/api/bookstore/bookInfoList";		
        link_Params = {
        	  	"rankingId": "${$.rankingId}",
        	  	"pageNum": page,
	          	"userPath": "classify/${sex}2"
          	};
         url = GetUrl(link_Params,link_Urlpath);`;							

		if(index+1 <= list.length - list.length%3){
				push(title, url, 1, 0.25);
				}
				else{ push(title, url, 0, 0.29);}

     });
  });


   category().map($=>{
     	classifyId = $.classifyId;
     	classifyName = $.classifyName;
     	subClassifyList = $.subClassifyList;	    
     	subClassifyList.splice(0,1).map($=>{      			
     	subClassifyName = $.subClassifyName;
     	push(classifyName+'🍁'+subClassifyName, null, 1, 1);
     	categoryRankTypeList = $.categoryRankTypeList; 	 	
     	categoryRankTypeList.map($=>{
     		name = $.name
     		push(name, null, 1, 1);  
     		list = $.subResultBOList;				
     		list.map(($,index)=>{
     		title = $.name;    	    
     		sex =classifyName=="男生"?"male":"female";

	      url=  `@js:
	      link_Urlpath = "/api/bookstore/bookInfoList";		
        link_Params = {
        	  	"tagId": "",
        	  	"numberRangeLevel": "0",
        	  	"sort": "0",
        	  	"serialType": "-1",
        	  	"pageNum": page,
	          	"userPath": "classify/${sex}/bookList"
          	};
          	if("${name}" == "题材"){
          	link_Params.subClassifyId = "${$.id}";
          	}else{
          		link_Params.labelId = "${$.id}";
           	link_Params.subClassifyId = "${classifyId}";
          	}
         url = GetUrl(link_Params,link_Urlpath);`;					

				 if(list.length > 3&&list.length!=4){
		if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
				}
				else if(list.length == 4){ push(title, url, 1, 0.4);}
				else{ push(title, url, 1, 0.25);}

				      });
         });
     });
  });

 JSON.stringify(sort);

