try {
  $$$ = JSON.parse(source.getVariable());
  if ($$$ == null || typeof $$$ !== 'object' || Array.isArray($$$)) {
    throw new Error();
  }
  if ($$$.custom == null) $$$.custom = '';
  if ($$$.suffix == null) $$$.suffix = '';
} catch (e) {
  $$$ = original;
  put($$$);
}

function put(data) {
  return source.setVariable(JSON.stringify(data));
}

function cur() {
  var s = 'https://manwa.me';
  try {
    var o = JSON.parse(source.getVariable());
    if (o.custom) s = o.custom;
    else if (o.suffix && /^[a-z]{1,2}$/.test(o.suffix)) s = 'https://manwa' + o.suffix + '.cc';
  } catch (e) {}
  return s;
}

//login：✓保存触发——应用自定义域名（真登录走网页 /login）
function login() {
  var raw = '';
  try { raw = String(JSON.parse(source.getLoginInfo())['自定义域名(2字母或完整网址)'] || '').trim(); } catch (e) {}
  if (raw) {
    var s = raw.toLowerCase().replace(/[^a-z0-9.:\/-]/g, '').slice(0, 60);
    if (/^[a-z]{1,2}$/.test(s)) {
      $$$.suffix = s;
      $$$.custom = '';
      put($$$);
      java.toast('已设置域名：' + cur());
    } else if (s.indexOf('.') > 0) {
      if (s.indexOf('://') < 0) s = 'https://' + s;
      $$$.custom = s.replace(/\/+$/, '');
      $$$.suffix = '';
      put($$$);
      java.toast('已设置域名：' + cur());
    } else {
      java.toast('域名格式不对：2个字母或完整域名');
    }
  } else {
    java.toast('当前接口：' + cur());
  }
}

function clearSuffix() {
  $$$.suffix = '';
  $$$.custom = '';
  put($$$);
  java.log('[manwa] 清除后 getVariable=' + source.getVariable());
  java.toast('已清除，使用默认域名');
}

function show() {
  java.toast('当前接口：' + cur());
}

